#!/bin/bash
set -e
cd "$(dirname "$0")"
echo "Applying client list files..."
mkdir -p src/lib/clients
cat > src/lib/clients/data.ts.b64 <<'B64EOF'

B64EOF
base64 -d < "src/lib/clients/data.ts.b64" > "src/lib/clients/data.ts"
rm "src/lib/clients/data.ts.b64"
mkdir -p src/features/clients
cat > src/features/clients/ClientRow.tsx.b64 <<'B64EOF'

B64EOF
base64 -d < "src/features/clients/ClientRow.tsx.b64" > "src/features/clients/ClientRow.tsx"
rm "src/features/clients/ClientRow.tsx.b64"
mkdir -p src/app
cat > src/app/explore.tsx.b64 <<'B64EOF'

B64EOF
base64 -d < "src/app/explore.tsx.b64" > "src/app/explore.tsx"
rm "src/app/explore.tsx.b64"

python3 - <<'PYEDIT'
import io
p='src/components/app-tabs.tsx'
s=open(p).read()
assert '<NativeTabs.Trigger.Label>Explore</NativeTabs.Trigger.Label>' in s, 'app-tabs label not found'
s=s.replace('<NativeTabs.Trigger.Label>Explore</NativeTabs.Trigger.Label>','<NativeTabs.Trigger.Label>Clients</NativeTabs.Trigger.Label>')
open(p,'w').write(s)

p='src/app/index.tsx'
s=open(p).read()
old_imp="import { Pressable, RefreshControl, ScrollView, StyleSheet, View, useColorScheme } from 'react-native';"
new_imp="import { Alert, Pressable, RefreshControl, ScrollView, StyleSheet, View, useColorScheme } from 'react-native';"
assert old_imp in s, 'index.tsx react-native import not found'
s=s.replace(old_imp,new_imp,1)

anchor="  const onRefresh = useCallback(() => {"
assert anchor in s, 'index.tsx onRefresh anchor not found'
handler = """  // Triage rows carry only a destination slug, never a client id, so a press
  // cannot yet open a specific record. Surfacing that honestly beats an inert
  // tap. Adding `clientId` to TriageItem is the next slice.
  const handleNavigate = useCallback((href: string) => {
    const label =
      href === 'clients'
        ? 'Clients'
        : href === 'itr-generation'
          ? 'ITR filings'
          : href === 'gst-module'
            ? 'GST returns'
            : href === 'documents'
              ? 'Documents'
              : href === 'invoicing'
                ? 'Invoices'
                : href;
    Alert.alert(
      label,
      href === 'clients'
        ? 'Open the Clients tab to see your active clients.'
        : 'This screen is not built yet.',
    );
  }, []);

"""
s=s.replace(anchor, handler+anchor, 1)

old_nav='                onNavigate={() => {}}'
assert old_nav in s, 'index.tsx onNavigate not found'
s=s.replace(old_nav,'                onNavigate={handleNavigate}',1)
open(p,'w').write(s)
print('patched app-tabs.tsx and index.tsx')
PYEDIT

echo "Done."
